-- ═══════════ Ajdodlar: ism, unvon, tarjimai hol ═══════════
UPDATE heroes SET name_ru = 'Абу Райхан Беруни', title_ru = 'Энциклопедический учёный', bio_ru = 'Учёный, родившийся в хорезмском городе Кят. Написал более 150 трудов по астрономии, географии, истории и минералогии.' WHERE slug = 'abu-rayhon-beruniy';
UPDATE heroes SET name_ru = 'Мирзо Улугбек', title_ru = 'Царь-учёный', bio_ru = 'Великий астроном и государственный деятель, внук Амира Темура. Построил в Самарканде обсерваторию и составил каталог из 1018 звёзд.' WHERE slug = 'mirzo-ulugbek';
UPDATE heroes SET name_ru = 'Абу Али ибн Сина', title_ru = 'Султан врачей', bio_ru = 'Врач и философ, родившийся в селении Афшана близ Бухары. Его «Канон врачебной науки» веками был учебником в Европе.' WHERE slug = 'ibn-sino';
UPDATE heroes SET name_ru = 'Имам аль-Бухари', title_ru = 'Имам хадисоведов', bio_ru = 'Хадисовед, родившийся в Бухаре. Его сборник «Аль-Джами ас-Сахих» считается одним из самых авторитетных источников хадисоведения.' WHERE slug = 'imom-al-buxoriy';
UPDATE heroes SET name_ru = 'Мухаммад аль-Хорезми', title_ru = 'Отец алгебры', bio_ru = 'Математик и астроном, родившийся в Хорезме. Его труд «Аль-джабр» лёг в основу алгебры, а имя — в основу слова «алгоритм».' WHERE slug = 'al-xorazmiy';
UPDATE heroes SET name_ru = 'Алишер Навои', title_ru = 'Низамиддин Мир Алишер', bio_ru = 'Великий поэт и мыслитель, основоположник узбекского литературного языка. Автор «Хамсы» и «Хазойин уль-маони».' WHERE slug = 'alisher-navoiy';
UPDATE heroes SET name_ru = 'Захириддин Мухаммад Бабур', title_ru = 'Поэт и полководец', bio_ru = 'Тимурид, родившийся в Андижане. Автор «Бабурнаме» и правитель, основавший государство Бабуридов в Индии.' WHERE slug = 'bobur';
UPDATE heroes SET name_ru = 'Абдулла Кадыри', title_ru = 'Основоположник узбекского романа', bio_ru = 'Писатель, родившийся в Ташкенте. «Минувшие дни» — первый роман в узбекской литературе. В 1938 году стал жертвой репрессий.' WHERE slug = 'abdulla-qodiriy';
UPDATE heroes SET name_ru = 'Джалолиддин Мангуберди', title_ru = 'Последний хорезмшах', bio_ru = 'Последний правитель государства Хорезмшахов. Более десяти лет вёл борьбу против монгольского нашествия.' WHERE slug = 'jaloliddin-manguberdi';
UPDATE heroes SET name_ru = 'Абдулла Авлони', title_ru = 'Основатель театра «Туран»', bio_ru = 'Ташкентский педагог, поэт и театральный деятель. Написал учебник «Тюркский цветник, или Нравственность», создал джадидскую театральную труппу.' WHERE slug = 'abdulla-avloniy';
UPDATE heroes SET name_ru = 'Абдулла Арипов', title_ru = 'Автор гимна', bio_ru = 'Поэт, родившийся в Кашкадарье. Написал текст Государственного гимна Республики Узбекистан. Перевёл на узбекский «Божественную комедию» Данте.' WHERE slug = 'abdulla-oripov';
UPDATE heroes SET name_ru = 'Абдурауф Фитрат', title_ru = 'Первый профессор', bio_ru = 'Бухарский учёный, драматург и музыковед. Написал «Спор», добился нотной записи Шашмакома, одним из первых среди узбекских учёных получил звание профессора.' WHERE slug = 'abdurauf-fitrat';
UPDATE heroes SET name_ru = 'Абу Наср аль-Фараби', title_ru = 'Второй учитель', bio_ru = 'Философ и музыковед, родившийся в Фарабе. Назван «Вторым учителем» после Аристотеля. Написал более 160 трудов.' WHERE slug = 'abu-nasr-forobiy';
UPDATE heroes SET name_ru = 'Абулгази Бахадурхан', title_ru = 'Хан-историк', bio_ru = 'Хивинский хан и учёный-историк. Написал «Родословную тюрок» — труд, служащий историкам важным источником.' WHERE slug = 'abulgozi-bahodirxon';
UPDATE heroes SET name_ru = 'Ахмад аль-Фергани', title_ru = 'Толкователь звёзд', bio_ru = 'Великий астроном, родившийся в Фергане. Работал в багдадском «Доме мудрости», создал прибор для измерения уровня воды Нила. В Европе его знали как «Альфраганус».' WHERE slug = 'ahmad-al-fargoniy';
UPDATE heroes SET name_ru = 'Али Кушчи', title_ru = 'Птолемей своего времени', bio_ru = 'Самаркандский астроном, ученик и соратник Улугбека. Внёс большой вклад в завершение «Зидж-и джадид-и Гурагани».' WHERE slug = 'ali-qushchi';
UPDATE heroes SET name_ru = 'Анбар Атын', title_ru = 'Поэтесса-отын', bio_ru = 'Кокандская поэтесса и учительница. Её называли «отын» за то, что она давала уроки девочкам махалли. В стихах воспевала справедливость и просвещение.' WHERE slug = 'anbar-otin';
UPDATE heroes SET name_ru = 'Бабарахим Машраб', title_ru = 'Поэт-дервиш', bio_ru = 'Наманганский поэт и мыслитель. Жизнь провёл в странствиях, его стихи широко разошлись в народе.' WHERE slug = 'boborahim-mashrab';
UPDATE heroes SET name_ru = 'Бумын-каган', title_ru = 'Основатель Тюркского каганата', bio_ru = 'Бумын-каган — правитель, который в середине VI века объединил тюркские племена Алтая и Южной Сибири и основал Тюркский каганат. В 552 году он был провозглашён «каганом». Основанное им государство вскоре расширилось до берегов Сырдарьи и Аральского моря.' WHERE slug = 'bumin-xoqon';
UPDATE heroes SET name_ru = 'Чулпан', title_ru = 'Поэт пробуждения', bio_ru = 'Поэт и писатель, родившийся в Андижане. Настоящее имя — Абдулхамид Сулейман оглы. Известен романом «Ночь и день» и поэтическими сборниками.' WHERE slug = 'cholpon';
UPDATE heroes SET name_ru = 'Дильбар Абдурахманова', title_ru = 'Первая женщина-дирижёр Узбекистана', bio_ru = 'Дильбар Абдурахманова — скрипачка, дирижёр и педагог, родившаяся в 1936 году; считается первой женщиной-дирижёром в Узбекистане. Почти полвека проработала в театре оперы и балета имени Алишера Навои и продирижировала более чем 60 оперными и балетными спектаклями.' WHERE slug = 'dilbar-abdurahmonova';
UPDATE heroes SET name_ru = 'Эркин Вахидов', title_ru = 'Поэт «Дивана молодости»', bio_ru = 'Поэт и драматург, родившийся в Фергане. Известен произведениями «Диван молодости» и «Восстание душ». Герой Узбекистана.' WHERE slug = 'erkin-vohidov';
UPDATE heroes SET name_ru = 'Мухаммад Рахимхан Феруз', title_ru = 'Хан-поэт', bio_ru = 'Хивинский хан, поэт и покровитель музыки. Составил диван под псевдонимом «Феруз», открыл в Хиве литографию; его наставником был Агахи.' WHERE slug = 'feruz';
UPDATE heroes SET name_ru = 'Гафур Гулям', title_ru = 'Автор «Озорника»', bio_ru = 'Ташкентский поэт и писатель. Известен повестью «Озорник» и стихотворением «Ты не сирота». Академик Академии наук.' WHERE slug = 'gafur-gulom';
UPDATE heroes SET name_ru = 'Гавхаршад-бегим', title_ru = 'Властная царица', bio_ru = 'Супруга Шахруха Мирзы, мать Улугбека. Фактически сама управляла делами государства, построила в Герате два крупных медресе.' WHERE slug = 'gavharshod-begim';
UPDATE heroes SET name_ru = 'Ибрайим Юсупов', title_ru = 'Народный поэт Каракалпакстана', bio_ru = 'Ибрайим Юсупов (1929–2008) — народный поэт Узбекистана и Каракалпакстана, Герой Узбекистана. Создал множество поэтических сборников и сценических произведений, переводил на каракалпакский язык жемчужины мировой литературы.' WHERE slug = 'ibrayim-yusupov';
UPDATE heroes SET name_ru = 'Гиясиддин Джамшид Каши', title_ru = 'Мастер вычислений', bio_ru = 'Один из ведущих математиков обсерватории Улугбека. Написал «Ключ арифметики», был одним из инициаторов проекта обсерватории.' WHERE slug = 'giyosiddin-koshiy';
UPDATE heroes SET name_ru = 'Халима Насырова', title_ru = 'Первая звезда узбекской оперы', bio_ru = 'Халима Насырова — певица и актриса, родившаяся в 1913 году в кишлаке Таглык близ Коканда; создала собственную школу в узбекском оперном искусстве. Исполняла главные партии в первых узбекских операх и прославилась как неповторимая исполнительница узбекских народных песен.' WHERE slug = 'halima-nosirova';
UPDATE heroes SET name_ru = 'Халима Худайбердыева', title_ru = 'Хозяйка огненных строк', bio_ru = 'Халима Худайбердыева — известная поэтесса, родившаяся в 1947 году в Баяутском районе Сырдарьинской области. Прославилась как певица чаяний узбекской женщины и в 1992 году удостоена звания «Народный поэт Узбекистана».' WHERE slug = 'halima-xudoyberdiyeva';
UPDATE heroes SET name_ru = 'Хусейн Байкара', title_ru = 'Правитель-поэт', bio_ru = 'Гератский правитель-тимурид и поэт. Управлял Хорасаном 37 лет, писал стихи под псевдонимом «Хусайни», школьный друг Навои.' WHERE slug = 'husayn-boyqaro';
UPDATE heroes SET name_ru = 'Исхакхан Ибрат', title_ru = 'Путешественник и издатель', bio_ru = 'Просветитель, языковед и один из первых узбекских издателей из Тураккургана. Составил шестиязычный словарь, открыл типографию в своём кишлаке.' WHERE slug = 'ishoqxon-ibrat';
UPDATE heroes SET name_ru = 'Исмаил Самани', title_ru = 'Основатель государства Саманидов', bio_ru = 'Исмаил Самани (849–907) — основатель государства Саманидов, правитель, объединивший весь Мавераннахр в единое сильное государство. Его столицей был город Бухара. Благодаря мудрому и справедливому правлению остался в истории под именем «амири мози».' WHERE slug = 'ismoil-somoniy';
UPDATE heroes SET name_ru = 'Истеми-каган', title_ru = 'Ябгу-каган — предводитель западных походов', bio_ru = 'Истеми-каган — правитель, возглавивший в Тюркском каганате походы тюрок на запад; ему был присвоен титул «Ябгу-каган». При нём каганат заключил союз с Ираном, разгромил государство эфталитов и стал活но участвовать в торговле по Великому шёлковому пути.' WHERE slug = 'istami-xoqon';
UPDATE heroes SET name_ru = 'Камолиддин Бехзод', title_ru = 'Рафаэль Востока', bio_ru = 'Великий гератский живописец. В двадцать три года возглавил гератскую школу миниатюры;写ал портреты Навои и Хусейна Байкары.' WHERE slug = 'kamoliddin-behzod';
UPDATE heroes SET name_ru = 'Канишка', title_ru = 'Правитель Кушанского царства', bio_ru = 'Канишка — самый известный правитель могущественного Кушанского царства, правившего в I–III веках нашей эры. При нём царство достигло вершины расцвета, строились новые города и широко распространился буддизм. Кушанское государство было одним из величайших царств своего времени наряду с Римом, Парфией и Китаем.' WHERE slug = 'kanishka';
UPDATE heroes SET name_ru = 'Махмудходжа Бехбуди', title_ru = 'Лидер джадидов', bio_ru = 'Просветитель, родившийся в Самарканде. Написал первую узбекскую драму «Отцеубийца», издавал газету «Самарканд» и журнал «Ойина».' WHERE slug = 'mahmudxoja-behbudiy';
UPDATE heroes SET name_ru = 'Мукаррама Тургунбаева', title_ru = 'Основательница ансамбля «Бахор»', bio_ru = 'Мукаррама Тургунбаева — танцовщица, балетмейстер и педагог, родившаяся в 1913 году близ Ферганы; считается одной из основательниц узбекской школы танца. В 1957 году создала знаменитый женский танцевальный ансамбль «Бахор» и руководила им до конца жизни.' WHERE slug = 'mukarrama-turgunboyeva';
UPDATE heroes SET name_ru = 'Мунавваркари Абдурашидханов', title_ru = 'Адиби аввал', bio_ru = 'Ташкентский просветитель. В 1901 году открыл джадидскую школу, написал учебник «Адиби аввал», стал первым ректором Туркестанского народного университета.' WHERE slug = 'munavvarqori';
UPDATE heroes SET name_ru = 'Мунис Хорезми', title_ru = 'Летописец Хорезма', bio_ru = 'Поэт и историк, родившийся в кишлаке Кыят близ Хивы. Начал летопись «Фирдавс уль-икбал», был писцом указов при дворе.' WHERE slug = 'munis-xorazmiy';
UPDATE heroes SET name_ru = 'Муканна', title_ru = 'Предводитель восстания «людей в белом»', bio_ru = 'Муканна (настоящее имя Хашим ибн Хаким) — предводитель восстания «людей в белом», поднявшегося в VIII веке в Мавераннахре против гнёта арабского халифата. Прозвище «Муканна», то есть «Закрытый покрывалом», получил за то, что закрывал голову и лицо синей завесой. Восстание длилось в 769–783 годах.' WHERE slug = 'muqanna';
UPDATE heroes SET name_ru = 'Абу Бакр Наршахи', title_ru = 'Автор «Истории Бухары»', bio_ru = 'Абу Бакр Мухаммад ибн Джафар Наршахи (899–959) — историк, родившийся в селении Наршах близ Бухары. Написанная им в 943–944 годах на арабском языке «История Бухары» считается древнейшим историческим трудом Средней Азии, созданным местным автором и дошедшим до нас полностью.' WHERE slug = 'narshaxiy';
UPDATE heroes SET name_ru = 'Надира', title_ru = 'Царица-поэтесса', bio_ru = 'Поэтесса и государственный деятель, родившаяся в Андижане. Настоящее имя — Махларайим. Фактически сама управляла государством в Коканде, строила медресе.' WHERE slug = 'nodira';
UPDATE heroes SET name_ru = 'Агахи', title_ru = 'Владелец пятидесяти книг', bio_ru = 'Хорезмский поэт, историк и переводчик. Продолжил дело своего дяди Муниса, написал пять исторических трудов, занимался распределением воды — мирабством.' WHERE slug = 'ogahiy';
UPDATE heroes SET name_ru = 'Айбек', title_ru = 'Автор романа «Навои»', bio_ru = 'Ташкентский писатель и поэт. Настоящее имя — Муса Ташмухамедов. Написал романы «Священная кровь» и «Навои», был академиком Академии наук.' WHERE slug = 'oybek';
UPDATE heroes SET name_ru = 'Озод Шарафиддинов', title_ru = 'Учёный, вернувший Чулпана народу', bio_ru = 'Озод Шарафиддинов — известный литературовед, критик и переводчик, родившийся в 1929 году близ Коканда. Изучил творчество репрессированного Чулпана и вернул его читателям, был главным редактором журнала «Мировая литература» и в 2002 году удостоен звания «Герой Узбекистана».' WHERE slug = 'ozod-sharafiddinov';
UPDATE heroes SET name_ru = 'Сараймульк-ханым', title_ru = 'Биби-ханым', bio_ru = 'Старшая жена Амира Темура. Женившись на ней, Темур получил титул «Кураган». Воспитывала Улугбека и других царевичей, построила в Самарканде медресе.' WHERE slug = 'saroymulkxonim';
UPDATE heroes SET name_ru = 'Ширак', title_ru = 'Самоотверженный сакский пастух', bio_ru = 'Ширак — пастух из сакского племени. Когда войско персидского царя Дария I вторглось в страну, он под видом проводника намеренно завёл врага в безводную пустыню и отдал жизнь за родину. Предание о его подвиге записал историк Полиэн.' WHERE slug = 'shiroq';
UPDATE heroes SET name_ru = 'Спитамен', title_ru = 'Согдийский полководец', bio_ru = 'Спитамен — согдийский полководец, боровшийся против нашествия Александра Македонского. Объединив согдийцев, бактрийцев и саков, он три года оказывал захватчикам упорное сопротивление. Погиб в 328 году до нашей эры.' WHERE slug = 'spitamen';
UPDATE heroes SET name_ru = 'Тамара Ханум', title_ru = 'Первая ласточка узбекского танца', bio_ru = 'Тамара Ханум (настоящее имя Тамара Артёмовна Петросян) — танцовщица, певица и балетмейстер, родившаяся в 1906 году в Фергане. Вместе с Уста Алимом Камиловым и Мукаррамой Тургунбаевой стала одной из основательниц узбекской профессиональной школы танца и познакомила с узбекским танцем весь мир.' WHERE slug = 'tamara-xonim';
UPDATE heroes SET name_ru = 'Томирис', title_ru = 'Царица массагетов', bio_ru = 'Томирис — царица массагетов, жившая в VI веке до нашей эры. Когда персидский царь Кир II вторгся в её страну, воины под её предводительством разгромили захватчиков. Её имя стало символом защиты родины.' WHERE slug = 'tomaris';
UPDATE heroes SET name_ru = 'Убайдулла Ходжаев', title_ru = 'Первый адвокат', bio_ru = 'Ташкентский юрист и издатель. Один из первых узбекских адвокатов, организатор газеты «Садои Туркистон».' WHERE slug = 'ubaydulla-xojayev';
UPDATE heroes SET name_ru = 'Увайси', title_ru = 'Мастерица чистанов', bio_ru = 'Маргиланская поэтесса и наставница. Настоящее имя — Джахан. При дворе учила поэзии Надиру и других женщин, известна своими стихотворными загадками — чистанами.' WHERE slug = 'uvaysiy';
UPDATE heroes SET name_ru = 'Заратуштра', title_ru = 'Основатель зороастризма', bio_ru = 'Заратуштра — основатель зороастризма, историческая личность, жившая в первой половине I тысячелетия до нашей эры. Главным правилом его учения были благая мысль, благое слово и благое дело. Священная книга зороастризма называется «Авеста».' WHERE slug = 'zardusht';
UPDATE heroes SET name_ru = 'Зебо Ганиева', title_ru = 'Героиня сцены и поля боя', bio_ru = 'Зебо Ганиева родилась в 1923 году и прославилась в годы Второй мировой войны как искусная разведчица и легендарный снайпер. После войны работала киноактрисой, а затем историком и востоковедом.' WHERE slug = 'zebo-ganiyeva';
UPDATE heroes SET name_ru = 'Зульфия', title_ru = 'Народная поэтесса', bio_ru = 'Ташкентская поэтесса. Известна стихами вроде «Весна пришла, тебя спросив», лауреат международной премии имени Джавахарлала Неру. Премия её имени вручается девушкам.' WHERE slug = 'zulfiya';
UPDATE heroes SET name_ru = 'Амир Темур', title_ru = 'Сохибкиран', bio_ru = 'Великий полководец и государственный деятель. В 1370 году основал в Мавераннахре централизованное государство со столицей в Самарканде.' WHERE slug = 'amir-temur';
UPDATE heroes SET name_ru = 'Имам ат-Тирмизи', title_ru = 'Великий хадисовед', bio_ru = 'Имам ат-Тирмизи (824–892) — великий хадисовед, родившийся в селении Буг близ Термеза. Его труд «Аль-Джами ас-сахих» («Сунан ат-Тирмизи») считается одной из шести самых достоверных книг хадисов исламского мира — «кутуб ситта».' WHERE slug = 'imom-at-termiziy';
UPDATE heroes SET name_ru = 'Махмуд аз-Замахшари', title_ru = 'Великий учёный-языковед', bio_ru = 'Махмуд аз-Замахшари (1075–1144) — языковед, литератор, учёный в области тафсира и хадиса, родившийся в хорезмском селении Замахшар. Прославился на Востоке и Западе тафсиром «Аль-Кашшаф» и трудом «Мукаддимат уль-адаб», а за жизнь и труды в Мекке получил прозвище «Джаруллах».' WHERE slug = 'mahmud-zamaxshariy';
UPDATE heroes SET name_ru = 'Бурханиддин Маргинани', title_ru = 'Автор «Хидои», великий факих', bio_ru = 'Бурханиддин Маргинани — великий факих, родившийся в местечке Риштан Маргилана, автор труда «Хидоя», ставшего основным учебником ханафитского фикха. Последние годы жизни провёл в Самарканде и похоронен на тамошнем кладбище Чокардиза.' WHERE slug = 'burhoniddin-marginoniy';
UPDATE heroes SET name_ru = 'Наджмиддин Кубро', title_ru = 'Основатель тариката кубравия', bio_ru = 'Наджмиддин Кубро (1145–1221) — знаменитый шейх, крупный учёный-суфий, народный герой и пламенный поэт, основатель тариката кубравия. Родился в селении Саят близ Хивы, погиб мучеником при обороне города от монголов.' WHERE slug = 'najmiddin-kubro';
UPDATE heroes SET name_ru = 'Бахауддин Накшбанд', title_ru = 'Основатель тариката накшбандия', bio_ru = 'Бахауддин Накшбанд (1318–1389) — великий суфий, основавший тарикат накшбандия, родившийся в селении Касри Хиндуван (Касри Орифон) под Бухарой. Суть его учения выражена в девизе «Даст ба кору, дил ба ёр!» («Рука в работе, сердце с Богом»).' WHERE slug = 'bahouddin-naqshband';
UPDATE heroes SET name_ru = 'Мухаммад Аминходжа Мукими', title_ru = 'Народный поэт, мастер сатиры', bio_ru = 'Мухаммад Аминходжа Мукими (1850–1903) — поэт и мыслитель, один из основоположников узбекской демократической литературы. Жил и творил в Коканде, известен произведением «Саёхатнаме» и почти тридцатью сатирическими сочинениями.' WHERE slug = 'muqimiy';
UPDATE heroes SET name_ru = 'Закирджан Фуркат', title_ru = 'Поэт-просветитель и публицист', bio_ru = 'Закирджан Фуркат (1859–1909) — прогрессивный поэт, мыслитель и публицист, один из основоположников узбекской публицистики. Родился в Коканде, пропагандировал знания и просвещение в «Туркистон вилоятининг газети», конец жизни провёл в Яркенде.' WHERE slug = 'furqat';
UPDATE heroes SET name_ru = 'Абдулла Каххар', title_ru = 'Мастер рассказа', bio_ru = 'Абдулла Каххар (1907–1968) — народный писатель Узбекистана, автор романа «Мираж», повести «Сказки о былом» и десятков рассказов. Считается признанным мастером жанра рассказа в узбекской прозе.' WHERE slug = 'abdulla-qahhor';
UPDATE heroes SET name_ru = 'Абу Мансур аль-Матуриди', title_ru = 'Великий самаркандский учёный', bio_ru = 'Абу Мансур аль-Матуриди (870–946) — великий учёный, живший и творивший в Самарканде. Занимался богословскими знаниями при дворе царя Насра, был имам-хатибом большой соборной мечети Самарканда и написал такие труды, как «Китаб ат-таухид». Похоронен на самаркандском кладбище Чокардиза.' WHERE slug = 'abu-mansur-moturidiy';
UPDATE heroes SET name_ru = 'Ахмад Яссави', title_ru = 'Поэт-суфий, наставник', bio_ru = 'Ахмад Яссави — поэт-суфий, прославленный именем «Султан уль-орифин», и наставник, основавший новый тарикат. Его хикматы были собраны учениками и последователями в книгу «Диван мудрости».' WHERE slug = 'ahmad-yassaviy';
UPDATE heroes SET name_ru = 'Пахлаван Махмуд', title_ru = 'Поэт, философ и богатырь', bio_ru = 'Пахлаван Махмуд (1247–1326) — поэт, получивший за философские рубаи имя «Хорезмский Хайям», непобедимый борец и ремесленник-скорняк. Был главой общины футувватчи в Хиве, предводителем джаванмардов.' WHERE slug = 'pahlavon-mahmud';
UPDATE heroes SET name_ru = 'Ходжа Ахрар Вали', title_ru = 'Наставник тариката накшбандия', bio_ru = 'Ходжа Ахрар Вали (1404–1490) — крупный наставник тариката накшбандия. Родился в селении Багистан близ Шаша (нынешнего Ташкента), действовал в Самарканде, построил более 20 медресе и ханак и тратил своё богатство на благо народа.' WHERE slug = 'xoja-ahror-valiy';
UPDATE heroes SET name_ru = 'Суфи Аллаяр', title_ru = 'Поэт-суфий', bio_ru = 'Суфи Аллаяр — поэт-суфий, автор трудов «Сабот уль-оджизин» и «Маслак уль-муттакин». Родился в селении Минглар Каттакурганского бекства, учился в Бухаре и на пути суфизма достиг степени валиуллах.' WHERE slug = 'sofi-olloyor';
UPDATE heroes SET name_ru = 'Турди Фароги', title_ru = 'Поэт классической сатиры', bio_ru = 'Турди Фароги — узбекский классический поэт, родившийся в XVII веке в Бухаре и творивший на узбекском и персидском языках. Знаменитой сатирой 1691 года о Субханкулихане поднял узбекскую сатиру на новую ступень после Алишера Навои; умер в Ходженте в 1699/1700 годах.' WHERE slug = 'turdi-farogiy';
UPDATE heroes SET name_ru = 'Мухаммад Шариф Гулхани', title_ru = 'Поэт и баснописец', bio_ru = 'Мухаммад Шариф Гулхани (примерно конец XVIII века — 20-е годы XIX века) — поэт, творивший на узбекском и таджикском языках, автор знаменитого произведения «Зарбулмасал». Жил в Намангане и Коканде, служил при дворе кокандских ханов Амира Алимхана и Амира Умархана.' WHERE slug = 'gulxaniy';
UPDATE heroes SET name_ru = 'Камиль Хорезми', title_ru = 'Поэт, каллиграф и музыковед', bio_ru = 'Камиль Хорезми (1825–1899) — поэт, каллиграф, переводчик и музыковед, живший и творивший в Хиве. Ввёл нотную систему «Танбурная линия» для записи узбекских мелодий и служил при дворе хивинского хана мирзабаши и диванбеги.' WHERE slug = 'komil-xorazmiy';
UPDATE heroes SET name_ru = 'Бердах', title_ru = 'Каракалпакский классический поэт', bio_ru = 'Бердах (1827–1900) — крупный представитель каракалпакской классической литературы, поэт и сказитель. Автор дастанов «Родословная», «Хорезм», «Айдос-бий» и множества стихов, воспевавших народную боль.' WHERE slug = 'berdaq';
UPDATE heroes SET name_ru = 'Ажинияз Косыбай улы', title_ru = 'Каракалпакский классический поэт', bio_ru = 'Ажинияз Косыбай улы (1824–1878) — поэт каракалпакского народа. В стихах упоминал себя под именем «Зевар». Известны стихотворения «Есть у меня страны» и «Будет», а избранные произведения не раз издавались на каракалпакском языке.' WHERE slug = 'ajiniyoz';
UPDATE heroes SET name_ru = 'Убайдулла Завки', title_ru = 'Кокандский поэт-сатирик', bio_ru = 'Завки (полное имя Убайдулла Салих оглы) — узбекский поэт-сатирик, живший и творивший в Коканде. Занимался ремеслом сапожника-махсидуза, в стихах обличал социальное неравенство и несправедливость.' WHERE slug = 'zavqiy';
UPDATE heroes SET name_ru = 'Аваз Утар', title_ru = 'Хорезмский поэт-просветитель', bio_ru = 'Аваз Утар (1884–1919) — узбекский поэт, родившийся и творивший в Хиве. В стихах воспевал идеи свободы, воли и просвещения; от него дошли диваны «Саодат уль-икбал» и «Диван Аваза».' WHERE slug = 'avaz-otar';
UPDATE heroes SET name_ru = 'Хамид Алимджан', title_ru = 'Узбекский поэт и драматург', bio_ru = 'Хамид Алимджан — известный узбекский поэт, драматург и учёный, родившийся в Джизаке. Автор дастанов «Зайнаб и Аман», «Ойгуль и Бахтияр», «Семург» и множества поэтических сборников.' WHERE slug = 'hamid-olimjon';
UPDATE heroes SET name_ru = 'Усман Насыр', title_ru = 'Поэт и переводчик', bio_ru = 'Усман Насыр (1912–1944) — известный узбекский поэт и переводчик, автор поэтических сборников «Сердце» и «Моя нежность». Стал жертвой репрессий 1937 года, конец жизни провёл в тюрьмах Магаданской и Кемеровской областей.' WHERE slug = 'usmon-nosir';
UPDATE heroes SET name_ru = 'Ташмухаммад Кары-Ниязи', title_ru = 'Математик, первый президент академии', bio_ru = 'Ташмухаммад Кары-Ниязи — учёный-математик, педагог и общественный деятель, первый президент Академии наук Узбекистана (1943–1947). Автор первых учебников на узбекском языке по элементарной и высшей математике.' WHERE slug = 'qori-niyoziy';
UPDATE heroes SET name_ru = 'Хабиб Абдуллаев', title_ru = 'Учёный-геолог, академик', bio_ru = 'Хабиб Абдуллаев (1912–1962) — учёный-геолог, доктор геолого-минералогических наук, академик Академии наук Узбекистана и её президент с 1956 года. Первым выделил Среднюю Азию как отдельную металлогеническую провинцию и глубоко изучил геологию месторождений.' WHERE slug = 'habib-abdullayev';
UPDATE heroes SET name_ru = 'Саид Ахмад', title_ru = 'Народный писатель Узбекистана', bio_ru = 'Саид Ахмад (1920–2007) — народный писатель Узбекистана и Герой Узбекистана, автор трилогии «Горизонт» и комедии «Бунт невесток». Снискал народную любовь сатирическими рассказами и вместе с супругой, поэтессой Саидой Зуннуновой, оставил неизгладимый след в узбекской литературе.' WHERE slug = 'said-ahmad';
UPDATE heroes SET name_ru = 'Уткир Хашимов', title_ru = 'Народный писатель Узбекистана', bio_ru = 'Уткир Хашимов — народный писатель Узбекистана, автор известных произведений «Дела мирские», «Меж двух дверей» и «Весна не вернётся». Более 50 его произведений разошлись тиражом почти в 2 миллиона экземпляров.' WHERE slug = 'otkir-hoshimov';
UPDATE heroes SET name_ru = 'Абдулхалик Гиждувани', title_ru = 'Основатель тариката ходжаган', bio_ru = 'Абдулхалик Гиждувани (1103–1179) — великий суфий, родившийся в Гиждуванском районе Бухарской области, основатель тариката ходжаган. Он привёл тарикат в соответствие с сунной пророка, очистив от новшеств, разработал восемь правил-рашха, и его учение впоследствии распространилось во многих краях как тарикат ходжаган-накшбандия.' WHERE slug = 'abdulholiq-gijduvoniy';
UPDATE heroes SET name_ru = 'Абдуллахан II', title_ru = 'Могущественный правитель Бухарского ханства', bio_ru = 'Абдуллахан II — крупнейший правитель Бухарского ханства из династии Шейбанидов (1583–1598), государственный деятель, полководец и покровитель науки, просвещения и культуры. При нём Бухара стала центром культуры и науки, а в стране развивалось градостроительство.' WHERE slug = 'abdullaxon-ii';
UPDATE heroes SET name_ru = 'Аброр Хидоятов', title_ru = 'Звезда узбекской сцены', bio_ru = 'Аброр Хидоятов (1900–1958) — великий актёр узбекского театра, народный артист Узбекистана. Творил на сцене с 1918 года и особенно запомнился народу исполнением роли Отелло у Шекспира.' WHERE slug = 'abror-hidoyatov';
UPDATE heroes SET name_ru = 'Абуль Муин ан-Насафи', title_ru = 'Учёный науки калама', bio_ru = 'Абуль Муин ан-Насафи (1027–1114) — великий представитель науки калама, родившийся в Насафе (нынешний Карши). Внёс большой вклад в широкое распространение в мире учения матуридия, основанного Абу Мансуром Матуриди, и написал знаменитые труды, такие как «Табсират аль-адилла».' WHERE slug = 'abul-muin-nasafiy';
UPDATE heroes SET name_ru = 'Аскад Мухтар', title_ru = 'Писатель и поэт', bio_ru = 'Аскад Мухтар — народный писатель Узбекистана, поэт и переводчик. Внёс большой вклад в узбекскую литературу романами «Сёстры», «Рождение», «Чинара» и поэтическими сборниками вроде «99 миниатюр».' WHERE slug = 'asqad-muxtor';
UPDATE heroes SET name_ru = 'Атаи', title_ru = 'Поэт-газелист эпохи Тимуридов', bio_ru = 'Атаи — узбекский поэт-газелист, живший и творивший в XV веке. По сообщению Алишера Навои, он был и среди поэтов двора Мирзо Улугбека. До нас дошёл его диван, включающий 260 газелей.' WHERE slug = 'atoyi';
UPDATE heroes SET name_ru = 'Батыр Закиров', title_ru = 'Основатель узбекской эстрады', bio_ru = 'Батыр Закиров (1936–1985) — знаменитый узбекский эстрадный певец, актёр и художник, народный артист Узбекистана (1965). Стал основателем узбекской современной профессиональной эстрадной песни и прославился песней «Арабское танго», исполненной на Московском фестивале 1957 года.' WHERE slug = 'botir-zokirov';
UPDATE heroes SET name_ru = 'Байсункар Мирза', title_ru = 'Покровитель искусства книги', bio_ru = 'Байсункар Мирза (1397–1433) — средний сын Шахруха Мирзы и Гавхаршад-бегим, царевич-тимурид. Внёс большой вклад в развитие искусства книги и миниатюры в Герате и распорядился составить научно-критический текст «Шахнаме» Фирдоуси.' WHERE slug = 'boysungur-mirzo';
UPDATE heroes SET name_ru = 'Чингиз Ахмаров', title_ru = 'Художник-монументалист', bio_ru = 'Чингиз Ахмаров (1912–1995) — художник-монументалист, народный художник Узбекистана (1964). В творчестве продолжил традиции восточной миниатюры и создал национальную школу живописи; настенные росписи на темы «Хамсы» в фойе театра Навои — среди его самых известных работ.' WHERE slug = 'chingiz-ahmarov';
UPDATE heroes SET name_ru = 'Дильшод отин (Дильшоди Барно)', title_ru = 'Поэтесса и учительница-отын', bio_ru = 'Дильшоди Барно (Дильшод отин) — узбекская поэтесса, просветительница и учительница-отын, обучавшая женщин и девочек грамоте; знаменитая поэтесса Анбар Атын была одной из её одарённых учениц. От неё дошли 91 узбекское и 51 таджикское стихотворение, а также труд «Тарихи муходжирон».' WHERE slug = 'dilshod-otin';
UPDATE heroes SET name_ru = 'Дурбек', title_ru = 'Автор «Юсуфа и Зулейхи»', bio_ru = 'Дурбек — узбекский поэт, живший в конце XIV и начале XV века. Автор знаменитого дастана «Юсуф и Зулейха», написанного в 1409 году; его жизнь и творчество связаны с городом Балх.' WHERE slug = 'durbek';
UPDATE heroes SET name_ru = 'Эльбек', title_ru = 'Джадидский поэт и языковед', bio_ru = 'Эльбек (настоящее имя Машрик Юнусов) — известный поэт джадидской эпохи, языковед и фольклорист, родившийся в 1898 году. Писал стихи и учебники для детей, собирал народные песни и стал невинной жертвой сталинских репрессий.' WHERE slug = 'elbek';
UPDATE heroes SET name_ru = 'Файзулла Ходжаев', title_ru = 'Государственный деятель и джадид', bio_ru = 'Файзулла Ходжаев — государственный и политический деятель, один из лидеров бухарского джадидского движения. После свержения бухарского эмира возглавил правительство Бухарской Народной Советской Республики, с 1925 года был председателем Совета народных комиссаров Узбекистана; жертва репрессий.' WHERE slug = 'fayzulla-xojayev';
UPDATE heroes SET name_ru = 'Хаким ат-Тирмизи', title_ru = 'Великий учёный-суфий', bio_ru = 'Хаким ат-Тирмизи — великий учёный-суфий и хадисовед, родившийся и выросший в Термезе, автор труда «Хатм уль-авлиё», заложившего основы теории валийства. Создал около четырёхсот трудов, а благодаря его ученикам и последователям в суфизме возникло течение хакимия.' WHERE slug = 'hakim-termiziy';
UPDATE heroes SET name_ru = 'Кунходжа', title_ru = 'Певец народной боли', bio_ru = 'Кунходжа Ибрагим оглы (1799–1880) — каракалпакский поэт. В стихах «Жнецы», «Белый камыш», «Пастухи» он воспевал жизнь каракалпакского народа, тяготы быта и надежды на приход лучших дней.' WHERE slug = 'kunxoja';
UPDATE heroes SET name_ru = 'Лютфиханум Сарымсакова', title_ru = 'Мать кино и театра', bio_ru = 'Лютфиханум Сарымсакова — известная актриса узбекского театра и кино, певица, получившая в 1937 году звание народной артистки Узбекистана. За образы заботливых матерей, созданные в кино и театре, коллектив театра и весь народ с уважением звали её «Ая».' WHERE slug = 'lutfixonim-sarimsoqova';
UPDATE heroes SET name_ru = 'Мавлоно Лутфи', title_ru = 'Малик уль-калам — царь слова', bio_ru = 'Мавлоно Лутфи (1366–1465) — крупный представитель узбекской классической поэзии; современники величали его «малик уль-калам», то есть царём слова. Его тюркский диван включает более 2774 бейтов стихов, а Алишер Навои почитал его как учителя.' WHERE slug = 'lutfiy';
UPDATE heroes SET name_ru = 'Миртемир', title_ru = 'Народный поэт Узбекистана', bio_ru = 'Миртемир (1910–1978) — народный поэт Узбекистана, автор лирической повести «Портрет» и искусный переводчик. Родился в кишлаке Икан близ города Туркестан, перевёл на узбекский язык киргизский народный эпос «Манас», а также произведения Пушкина, Некрасова и Руставели.' WHERE slug = 'mirtemir';
UPDATE heroes SET name_ru = 'Мухаммад Юсуф', title_ru = 'Народный поэт Узбекистана', bio_ru = 'Мухаммад Юсуф — народный поэт Узбекистана, родившийся в 1954 году в Мархаматском районе Андижанской области. Глубоко вошёл в сердце народа стихами, искренне воспевавшими Родину, мать и любовь.' WHERE slug = 'muhammad-yusuf';
UPDATE heroes SET name_ru = 'Адыл Якубов', title_ru = 'Народный писатель Узбекистана', bio_ru = 'Адыл Якубов (1926–2009) — народный писатель Узбекистана, автор романов «Сокровища Улугбека», «Совесть», «Древний мир». В 1956 году окончил филологический факультет Ташкентского государственного университета и является одним из крупных представителей узбекской прозы.' WHERE slug = 'odil-yoqubov';
UPDATE heroes SET name_ru = 'Урал Тансыкбаев', title_ru = 'Художник-пейзажист, мастер живописи', bio_ru = 'Урал Тансыкбаев (1904–1974) — художник-пейзажист, мастер живописи, народный художник Узбекистана (1944). С 30-х годов в его творчестве ведущее место занял жанр пейзажа; работы «Утро Кайраккумской ГЭС», «Весна в Узбекистане» хранятся в музеях республики и зарубежных стран.' WHERE slug = 'orol-tansiqboyev';
UPDATE heroes SET name_ru = 'Примкул Кадыров', title_ru = 'Народный писатель Узбекистана', bio_ru = 'Примкул Кадыров (1928–2010) — народный писатель Узбекистана, автор исторических романов «Звёздные ночи», посвящённого жизни Бабура, и его продолжения «Перевал поколений». Как учёный-литературовед создал также научные труды по языку и литературе.' WHERE slug = 'pirimqul-qodirov';
UPDATE heroes SET name_ru = 'Каффаль Шаши', title_ru = 'Великий факих и хадисовед', bio_ru = 'Каффаль Шаши (полное имя Абу Бакр Мухаммад ибн Али Исмаил Каффаль аш-Шаши аль-Кабир, 903–976) — знаменитый факих, хадисовед, языковед и поэт, родившийся в Шаше (Ташкенте), один из ведущих учёных шафиитского мазхаба. Прославился под именем «Хазрати Имам» (кратко Хастимом), а ташкентский комплекс Хазрати Имам возник вокруг его мавзолея.' WHERE slug = 'qaffol-shoshiy';
UPDATE heroes SET name_ru = 'Казизаде Руми', title_ru = 'Учитель Улугбека, астроном', bio_ru = 'Казизаде Руми — знаменитый астроном и математик, родившийся в 1337 году в городе Бурса и работавший в Самарканде, учитель Мирзо Улугбека. Современники называли его «Платоном своего времени».' WHERE slug = 'qozizoda-rumiy';
UPDATE heroes SET name_ru = 'Садриддин Айни', title_ru = 'Писатель и учёный', bio_ru = 'Садриддин Айни — писатель и учёный, творивший на узбекском и таджикском языках, первый президент Академии наук Таджикистана. Известен романами «Рабы», «Дохунда» и четырёхчастным произведением «Воспоминания».' WHERE slug = 'sadriddin-ayniy';
UPDATE heroes SET name_ru = 'Саккаки', title_ru = 'Поэт-касыдист эпохи Тимуридов', bio_ru = 'Саккаки — один из поэтов, творивших в XV веке в Самарканде и заложивших основу жанра касыды в узбекской литературе. Известен касыдами, посвящёнными Мирзо Улугбеку, и газелями.' WHERE slug = 'sakkokiy';
UPDATE heroes SET name_ru = 'Сайфи Сараи', title_ru = 'Поэт и переводчик', bio_ru = 'Сайфи Сараи (1321–1398) — известный поэт и переводчик узбекской классической литературы. В 1391 году переложил на тюркский язык «Гулистан» Саади и создал философско-нравственное произведение «Гулистони бит-турки».' WHERE slug = 'sayfi-saroyi';
UPDATE heroes SET name_ru = 'Мухаммад Шейбани-хан', title_ru = 'Основатель государства Шейбанидов', bio_ru = 'Мухаммад Шейбани-хан (1451–1510) — правитель, основавший государство Шейбанидов, полководец и поэт. В начале XVI века захватил Бухару, Самарканд и Ташкент и объединил Мавераннахр в составе единого государства.' WHERE slug = 'shayboniyxon';
UPDATE heroes SET name_ru = 'Шахрух Мирза', title_ru = 'Правитель державы Тимуридов', bio_ru = 'Шахрух Мирза (1377–1447) — сын Сохибкирана Амира Темура, правитель державы Тимуридов и отец Мирзо Улугбека. Благоустроил города Герат, Балх и Мерв и много покровительствовал развитию науки и культуры.' WHERE slug = 'shohrux-mirzo';
UPDATE heroes SET name_ru = 'Шукур Холмирзаев', title_ru = 'Народный писатель Узбекистана', bio_ru = 'Шукур Холмирзаев (1940–2005) — народный писатель Узбекистана, мастер узбекского рассказа. Родился в Байсунском районе Сурхандарьи, известен рассказами о природе и человеке, романами «Волосяной мост», «Динозавр».' WHERE slug = 'shukur-xolmirzayev';
UPDATE heroes SET name_ru = 'Сара Ишантураева', title_ru = 'Народная артистка Узбекистана', bio_ru = 'Сара Ишантураева — знаменитая актриса узбекского театра, народная артистка Узбекистана (1937). В академическом драматическом театре имени Хамзы исполняла главные роли Офелии, Дездемоны, Джамили, была и директором этого театра.' WHERE slug = 'sora-eshonturayeva';
UPDATE heroes SET name_ru = 'Тавалло', title_ru = 'Джадидский поэт и просветитель', bio_ru = 'Тавалло (настоящее имя Тулаган Ходжамьяров, 1883–1937) — ташкентский джадидский поэт, автор поэтического сборника «Равнак уль-ислом», изданного в 1916 году. Был одним из основателей товарищества «Нашриёт», в 1937 году стал жертвой репрессий и был реабилитирован в 1968 году.' WHERE slug = 'tavallo';
UPDATE heroes SET name_ru = 'Тимур Малик', title_ru = 'Герой обороны Ходжента', bio_ru = 'Тимур Малик — полководец, живший в XIII веке, правитель Ходжентской области. Мужественно оборонял островную крепость посреди Сырдарьи от войск Чингисхана и впоследствии стал соратником Джалолиддина Мангуберди.' WHERE slug = 'temur-malik';
UPDATE heroes SET name_ru = 'Тагай Мурад', title_ru = 'Народный писатель Узбекистана', bio_ru = 'Тагай Мурад (настоящее имя Менгноров Тагаймурад) — народный писатель Узбекистана, автор повести «Вечер, когда заржал конь» и романа «Поля, оставшиеся от отца». Родился в 1948 году в Денауском районе Сурхандарьинской области, умер в 2003 году в Ташкенте.' WHERE slug = 'togay-murod';
UPDATE heroes SET name_ru = 'Ташмухаммад Сарымсаков', title_ru = 'Учёный-математик, академик', bio_ru = 'Ташмухаммад Сарымсаков (1915–1995) — узбекский математик, академик и президент Академии наук Узбекистана (1946–52), ректор университета. Известен исследованиями по теории вероятностей и тем, что основал ташкентскую научную школу по топологии и функциональному анализу.' WHERE slug = 'toshmuhammad-sarimsoqov';
UPDATE heroes SET name_ru = 'Убай Арифов', title_ru = 'Учёный-физик, академик', bio_ru = 'Убай Арифов — учёный-физик, государственный и общественный деятель, академик Академии наук Узбекистана (1956) и её президент (1962–1966). Руководил институтами ядерной физики и электроники, изучал взаимодействие атомных частиц с поверхностью твёрдых тел.' WHERE slug = 'ubay-orifov';
UPDATE heroes SET name_ru = 'Яхья Гулямов', title_ru = 'Историк-археолог, академик', bio_ru = 'Яхья Гулямов (1908–1977) — учёный-историк и археолог, академик Академии наук Узбекистана. Изучил историю орошения Хорезма и создал в Узбекистане самобытную научную школу по истории и археологии.' WHERE slug = 'yahyo-gulomov';
UPDATE heroes SET name_ru = 'Юнус Раджаби', title_ru = 'Музыковед, народный артист', bio_ru = 'Юнус Раджаби — выдающийся представитель узбекского музыкального искусства: певец, инструменталист и композитор. Записал «Шашмаком» нотами и издал его в шести томах, был народным артистом Узбекистана и академиком Академии наук.' WHERE slug = 'yunus-rajabiy';
UPDATE heroes SET name_ru = 'Юсуф Хамадани', title_ru = 'Великий пир силсилы ходжаган', bio_ru = 'Ходжа Юсуф Хамадани (1048–1140) — великий представитель науки суфизма, пир, посеявший первые семена тариката ходжаган. Обучал мюридов в Бухаре и воспитал таких великих суфиев, как Ахмад Яссави и Абдулхалик Гиждувани.' WHERE slug = 'yusuf-hamadoniy';

