UPDATE historical_events SET title_ru = 'Тешик-Таш: находка ребёнка-неандертальца', description_ru = 'В пещере Тешик-Таш жили люди древнего каменного века. Найденные в пещере погребённые останки ребёнка-неандертальца стали открытием, прославившимся в мировой науке.' WHERE title_uz = 'Teshiktosh: neandertal bolasi topilmasi';
UPDATE historical_events SET title_ru = 'Сапаллитепа и Джаркутан — первое градостроительство', description_ru = 'В бронзовом веке в Сапаллитепа и Джаркутане развивались земледелие, ремёсла и зодчество, и сложилась первая градостроительная культура нашего края.' WHERE title_uz = 'Sopollitepa va Jarqo''ton — ilk shaharsozlik';
UPDATE historical_events SET title_ru = 'Формирование «Авесты»', description_ru = 'Древнейшие части «Авесты» — священной книги зороастризма — сложились на этой территории. Это один из важнейших письменных источников о древней истории нашего народа.' WHERE title_uz = '«Avesto»ning shakllanishi';
UPDATE historical_events SET title_ru = 'Первые государства: Великий Хорезм, Бактрия, Согдиана', description_ru = 'На нашей территории возникли первые государственные объединения — Великий Хорезм, Бактрийское царство и Согдиана.' WHERE title_uz = 'Ilk davlatlar: Katta Xorazm, Baqtriya, So''g''diyona';
UPDATE historical_events SET title_ru = 'Завоевание Ахеменидов', description_ru = 'Персидское государство Ахеменидов захватило наш край и разделило его на сатрапии. Хотя народ был вынужден платить тяжёлые налоги, борьба за свободу не прекращалась.' WHERE title_uz = 'Ahamoniylar istilosi';
UPDATE historical_events SET title_ru = 'Битва Томирис и Кира II', description_ru = 'Персидский царь Кир II вторгся в землю массагетов. Воины под предводительством царицы Томирис разгромили войско захватчиков.' WHERE title_uz = 'To''maris va Kir II jangi';
UPDATE historical_events SET title_ru = 'Подвиг Ширака', description_ru = 'Сакский пастух Ширак намеренно завёл войско Дария I в безводную пустыню и отдал жизнь за родину.' WHERE title_uz = 'Shiroq jasorati';
UPDATE historical_events SET title_ru = 'Поход Александра Македонского и восстание Спитамена', description_ru = 'Александр Македонский вторгся в Согдиану. Народное восстание под предводительством Спитамена три года оказывало захватчикам упорное сопротивление.' WHERE title_uz = 'Iskandar Maqduniy yurishi va Spitamen qo''zg''oloni';
UPDATE historical_events SET title_ru = 'Возвышение государства Кангюй', description_ru = 'Государство Кангюй, образовавшееся в среднем течении Сырдарьи, обрело могущество благодаря земледелию, скотоводству и торговле по Шёлковому пути.' WHERE title_uz = 'Qang'' davlatining yuksalishi';
UPDATE historical_events SET title_ru = 'Греко-Бактрийское государство', description_ru = 'В отделившемся от Селевкидов Греко-Бактрийском государстве слились греческая и местная культуры и возникло самобытное эллинистическое искусство.' WHERE title_uz = 'Yunon-Baqtriya davlati';
UPDATE historical_events SET title_ru = 'Государство Давань и «небесные кони»', description_ru = 'Государство Давань в Фергане прославилось породистыми скакунами — китайские императоры устраивали походы, чтобы завладеть этими конями.' WHERE title_uz = 'Dovon davlati va «samoviy arg''umoqlar»';
UPDATE historical_events SET title_ru = 'Открытие Великого шёлкового пути', description_ru = 'Великий шёлковый путь, связавший Китай со Средиземноморьем, прошёл через наш регион и превратил Самарканд и Бухару в центры мировой торговли.' WHERE title_uz = 'Buyuk ipak yo''lining ochilishi';
UPDATE historical_events SET title_ru = 'Расцвет центров буддизма', description_ru = 'В кушанское время поднялись храмы Фаязтепа и Каратепа — Термез стал крупным центром буддизма.' WHERE title_uz = 'Buddizm markazlari gullab-yashnashi';
UPDATE historical_events SET title_ru = 'Возвышение Кушанского царства', description_ru = 'Кушанское царство было одним из могущественнейших государств своего времени; расцвели торговля, градостроительство и культура.' WHERE title_uz = 'Kushon saltanatining yuksalishi';
UPDATE historical_events SET title_ru = 'Государство эфталитов', description_ru = 'Эфталиты («белые гунны») создали сильное государство и распространили влияние до Ирана и Индии; затем началась эпоха Тюркского каганата.' WHERE title_uz = 'Eftaliylar davlati';
UPDATE historical_events SET title_ru = 'Походы Кутейбы ибн Муслима', description_ru = 'Арабский полководец Кутейба ибн Муслим занял Бухару (709) и Самарканд (712). В Мавераннахр пришёл ислам.' WHERE title_uz = 'Qutayba ibn Muslim yurishlari';
UPDATE historical_events SET title_ru = 'Восстание Муканны', description_ru = '«Люди в белом» под предводительством Муканны восстали против гнёта арабского халифата. Восстание годами охватывало весь край.' WHERE title_uz = 'Muqanna qo''zg''oloni';
UPDATE historical_events SET title_ru = 'Деятельность Имама аль-Бухари', description_ru = 'Имам аль-Бухари — султан хадисоведения. Его сборник «Аль-джами ас-сахих» считается в исламском мире самым достоверным источником после Корана.' WHERE title_uz = 'Imom al-Buxoriy faoliyati';
UPDATE historical_events SET title_ru = 'Возвышение государства Саманидов', description_ru = 'При Саманидах возродилась местная государственность. Столица Бухара стала крупным центром науки и культуры Востока.' WHERE title_uz = 'Somoniylar davlatining yuksalishi';
UPDATE historical_events SET title_ru = 'Аль-Хорезми и рождение алгебры', description_ru = 'Мухаммад ибн Муса аль-Хорезми заложил основы алгебры; слово «алгоритм» произошло от его имени.' WHERE title_uz = 'Al-Xorazmiy va algebra fanining tug''ilishi';
UPDATE historical_events SET title_ru = 'Деятельность Имама ат-Тирмизи', description_ru = 'Великий хадисовед Имам ат-Тирмизи составил сборник «Сунан ат-Тирмизи» и внёс огромный вклад в развитие науки о хадисах.' WHERE title_uz = 'Imom at-Termiziy faoliyati';
UPDATE historical_events SET title_ru = 'Абу Наср аль-Фараби — «Второй учитель»', description_ru = 'Аль-Фараби развил философию, логику и науку о музыке и получил имя «Второй учитель». Его труд «Город добродетельных людей» выражает мечту о справедливом обществе.' WHERE title_uz = 'Abu Nasr Forobiy — «Ikkinchi muallim»';
UPDATE historical_events SET title_ru = 'Беруни и Ибн Сина — энциклопедические учёные', description_ru = 'Абу Райхан Беруни и Абу Али ибн Сина внесли огромный вклад в мировую науку: «Канон врачебной науки» 600 лет был учебником в Европе, а труды Беруни обогатили историю и географию.' WHERE title_uz = 'Beruniy va Ibn Sino — qomusiy olimlar';
UPDATE historical_events SET title_ru = 'Образование государства Амира Темура', description_ru = 'Амир Темур основал в Мавераннахре централизованное государство и сделал столицей Самарканд.' WHERE title_uz = 'Amir Temur davlatining tashkil topishi';
UPDATE historical_events SET title_ru = 'Строительство соборной мечети Биби-ханым', description_ru = 'После индийского похода Амир Темур возвёл в столице огромную соборную мечеть — она была одним из самых величественных сооружений своего времени.' WHERE title_uz = 'Bibixonim jome masjidi qurilishi';
UPDATE historical_events SET title_ru = 'Ангорская битва', description_ru = 'Амир Темур победил османского султана Баязида Молниеносного — это была одна из крупнейших битв в мировой истории.' WHERE title_uz = 'Anqara jangi';
UPDATE historical_events SET title_ru = 'Правление Улугбека в Самарканде', description_ru = 'Мирзо Улугбек управлял Мавераннахром почти сорок лет. При нём Самарканд стал научной столицей всего Востока.' WHERE title_uz = 'Ulug''bekning Samarqanddagi hukmronligi';
UPDATE historical_events SET title_ru = 'Медресе Улугбека на Регистане', description_ru = 'На площади Регистан поднялось медресе Улугбека — в нём наряду с религиозными науками преподавали математику и астрономию.' WHERE title_uz = 'Registonda Ulug''bek madrasasi';
UPDATE historical_events SET title_ru = 'Строительство обсерватории Улугбека', description_ru = 'Мирзо Улугбек построил самую передовую в мире обсерваторию; в ней был составлен точный каталог 1018 звёзд.' WHERE title_uz = 'Ulug''bek rasadxonasining qurilishi';
UPDATE historical_events SET title_ru = 'Герат — столица культуры Востока', description_ru = 'При Хусейне Байкаре в Герате творил Навои, Бехзод поднял школу миниатюры — город стал центром восточного Возрождения.' WHERE title_uz = 'Hirot — Sharq madaniyati poytaxti';
UPDATE historical_events SET title_ru = 'Навои создал «Хамсу»', description_ru = 'Алишер Навои создал первую полную «Хамсу» — пять поэм на тюркском языке — и показал всему миру мощь нашего родного языка.' WHERE title_uz = 'Navoiy «Xamsa»ni yaratdi';
UPDATE historical_events SET title_ru = 'Шейбаниды занимают Мавераннахр', description_ru = 'Кочевые узбеки под предводительством Мухаммада Шейбани-хана заняли государство Тимуридов и основали династию Шейбанидов.' WHERE title_uz = 'Shayboniylar Movarounnahrni egallashi';
UPDATE historical_events SET title_ru = 'Образование Хивинского ханства', description_ru = 'На территории Хорезма возникло независимое Хивинское ханство.' WHERE title_uz = 'Xiva xonligining tashkil topishi';
UPDATE historical_events SET title_ru = 'Битва при Панипате — держава Бабуридов', description_ru = 'Захириддин Мухаммад Бабур одержал победу в битве при Панипате и основал державу Бабуридов, правившую в Индии более трёх веков.' WHERE title_uz = 'Panipat jangi — boburiylar saltanati';
UPDATE historical_events SET title_ru = 'Династия Аштарханидов', description_ru = 'На бухарский трон взошла династия Аштарханидов (Джанидов). В это время продолжались строительство медресе и искусство книги.' WHERE title_uz = 'Ashtarxoniylar sulolasi';
UPDATE historical_events SET title_ru = 'Правление Абулгази Бахадурхана', description_ru = 'Хан и учёный Абулгази Бахадурхан написал труд «Родословная тюрок» и внёс бесценный вклад в изучение истории тюркских народов.' WHERE title_uz = 'Abulg''oziy Bahodirxon hukmronligi';
UPDATE historical_events SET title_ru = 'Образование Кокандского ханства', description_ru = 'В Ферганской долине образовалось Кокандское ханство. Так сложились три государства — Бухара, Хива и Коканд.' WHERE title_uz = 'Qo''qon xonligining tashkil topishi';
UPDATE historical_events SET title_ru = 'Династия Мангытов — Бухарский эмират', description_ru = 'Власть в Бухаре перешла к династии Мангытов, и государство стало называться Бухарским эмиратом.' WHERE title_uz = 'Mang''itlar sulolasi — Buxoro amirligi';
UPDATE historical_events SET title_ru = 'Формирование ансамблей Ичан-Калы', description_ru = 'В Хиве поднялись минареты, медресе и дворцы Ичан-Калы — этот комплекс впоследствии первым был внесён в список ЮНЕСКО.' WHERE title_uz = 'Ichan-qal''a ansambllari shakllanishi';
UPDATE historical_events SET title_ru = 'Время Умархана и Надиры', description_ru = 'В Коканде при Умархане (поэте Амирий) и царице Надире расцвели поэзия, искусство книги и зодчество.' WHERE title_uz = 'Umarxon va Nodira davri';
UPDATE historical_events SET title_ru = 'Захват Ташкента Российской империей', description_ru = 'Войска Российской империи захватили Ташкент — Туркестан превратился в колонию.' WHERE title_uz = 'Rossiya imperiyasining Toshkentni bosib olishi';
UPDATE historical_events SET title_ru = 'Туркестанское генерал-губернаторство', description_ru = 'На захваченных землях Российская империя учредила Туркестанское генерал-губернаторство — край перешёл под колониальное управление.' WHERE title_uz = 'Turkiston general-gubernatorligi';
UPDATE historical_events SET title_ru = 'Бухара и Хива попадают в зависимость от России', description_ru = 'Бухарский эмират (1868) и Хивинское ханство (1873) были превращены в государства, зависимые от Российской империи.' WHERE title_uz = 'Buxoro va Xiva Rossiyaga qaram bo''lishi';
UPDATE historical_events SET title_ru = 'Открытие новометодных (джадидских) школ', description_ru = 'Просветители-джадиды открыли новометодные школы, дававшие современные знания: они ставили целью пробудить нацию через науку.' WHERE title_uz = 'Yangi usul (jadid) maktablarining ochilishi';
UPDATE historical_events SET title_ru = 'Андижанское восстание', description_ru = 'Восстание под предводительством Дукчи Ишана поднялось против колониального гнёта и было жестоко подавлено.' WHERE title_uz = 'Andijon qo''zg''oloni';
UPDATE historical_events SET title_ru = '«Тараккий» — начало национальной печати', description_ru = 'Начала выходить одна из первых узбекских газет — «Тараккий»; национальная печать стала орудием пробуждения народного сознания.' WHERE title_uz = '«Taraqqiy» — milliy matbuot boshlanishi';
UPDATE historical_events SET title_ru = 'Драма Бехбуди «Отцеубийца»', description_ru = 'Махмудходжа Бехбуди написал первую узбекскую драму — «Отцеубийца». Показав на сцене трагедию невежества, он призвал народ к знанию.' WHERE title_uz = 'Behbudiyning «Padarkush» dramasi';
UPDATE historical_events SET title_ru = 'Восстание против мобилизации на тыловые работы', description_ru = 'После объявления о принудительном наборе на тыловые работы в годы Первой мировой войны поднялось народное восстание, охватившее весь край.' WHERE title_uz = 'Mardikorlikka qarshi qo''zg''olon';
UPDATE historical_events SET title_ru = 'Туркестанская автономия', description_ru = 'В Коканде была провозглашена Туркестанская автономия — первый опыт демократической государственности в крае. Через 72 дня она была ликвидирована большевиками.' WHERE title_uz = 'Turkiston muxtoriyati';
UPDATE historical_events SET title_ru = 'Образование Узбекской ССР', description_ru = 'В результате национально-территориального размежевания была образована Узбекская ССР.' WHERE title_uz = 'O''zbekiston SSR tashkil etilishi';
UPDATE historical_events SET title_ru = 'Перенос столицы в Ташкент', description_ru = 'Столица Узбекской ССР была перенесена из Самарканда в Ташкент.' WHERE title_uz = 'Poytaxt Toshkentga ko''chirilishi';
UPDATE historical_events SET title_ru = 'Большой террор', description_ru = 'В годы репрессий погибли Абдулла Кадыри, Чулпан, Фитрат и тысячи наших соотечественников. Их память чтят и сегодня.' WHERE title_uz = 'Katta qatag''on';
UPDATE historical_events SET title_ru = 'Годы Второй мировой войны', description_ru = 'Более 1,5 миллиона жителей Узбекистана были мобилизованы на фронт; наша страна приняла сотни заводов и тысячи детей-сирот.' WHERE title_uz = 'Ikkinchi jahon urushi yillari';
UPDATE historical_events SET title_ru = 'Начало Аральской трагедии', description_ru = 'Из-за хлопковой монокультуры воды Амударьи и Сырдарьи были отведены на поля — Аральское море начало высыхать.' WHERE title_uz = 'Orol fojiasining boshlanishi';
UPDATE historical_events SET title_ru = 'Ташкентское землетрясение', description_ru = 'Сильное землетрясение разрушило центр Ташкента; город был отстроен заново в короткий срок и обрёл новый облик.' WHERE title_uz = 'Toshkent zilzilasi';
UPDATE historical_events SET title_ru = 'Статус государственного языка для узбекского', description_ru = '21 октября узбекскому языку был присвоен статус государственного — это стало важным шагом на пути к независимости.' WHERE title_uz = 'O''zbek tiliga davlat tili maqomi';
UPDATE historical_events SET title_ru = 'Провозглашение независимости', description_ru = '31 августа 1991 года была провозглашена государственная независимость Республики Узбекистан. 1 сентября — День независимости.' WHERE title_uz = 'Mustaqillik e''lon qilinishi';
UPDATE historical_events SET title_ru = 'Принятие государственного флага', description_ru = '18 ноября был принят государственный флаг независимого Узбекистана — голубой, белый и зелёный цвета стали символом новой эпохи.' WHERE title_uz = 'Davlat bayrog''i qabul qilinishi';
UPDATE historical_events SET title_ru = 'Принятие Конституции', description_ru = '8 декабря 1992 года была принята Конституция Республики Узбекистан.' WHERE title_uz = 'Konstitutsiya qabul qilinishi';
UPDATE historical_events SET title_ru = 'Вступление в ООН', description_ru = '2 марта Узбекистан стал членом Организации Объединённых Наций — мировое сообщество признало новое государство.' WHERE title_uz = 'BMTga a''zo bo''lish';
UPDATE historical_events SET title_ru = 'Бухара в списке ЮНЕСКО', description_ru = 'Исторический центр Бухары был внесён в Список всемирного наследия ЮНЕСКО.' WHERE title_uz = 'Buxoro YUNESKO ro''yxatida';
UPDATE historical_events SET title_ru = 'Введение национальной валюты — сума', description_ru = 'С 1 июля 1994 года в обращение была введена национальная валюта — сум.' WHERE title_uz = 'Milliy valyuta — so''m muomalaga kiritilishi';
UPDATE historical_events SET title_ru = '«Год Амира Темура»', description_ru = 'Широко отмечалось 660-летие со дня рождения Сохибкирана, и наследие наших предков вновь обрело почёт.' WHERE title_uz = '«Amir Temur yili»';
UPDATE historical_events SET title_ru = 'Самарканд — «Перекрёсток культур»', description_ru = 'Самарканд был внесён в Список всемирного наследия ЮНЕСКО под названием «Перекрёсток культур».' WHERE title_uz = 'Samarqand — «Madaniyatlar chorrahasi»';

